INSERT INTO public.american_lessons (id,book_no,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question,grammar_card) VALUES ('am4_l43',4,8,43,'Are There Strangers in Space?','太空中有陌生人吗?','be bound to do(必定/注定要)、may/might have done(对过去的推测)、so + 形容词 + 倒装(so vast is the number that…)、let alone(更不用说)、it was not long before(不久就…)(NCE4 该课源无独立 KS 页,考点由课文结构自取;IP:源为 Anthony Michaelis《Are There Strangers in Space?》from The Weekend Telegraph 一篇论地外文明与射电通讯的科普文,系版权作品——已用 100% 原创行文复述其事实、无引用原句;具名 Bracewell 教授、Walter Sullivan 及其书均泛化为‘一位射电天文学家/一位科普作家的名著’;题材=天文·无害;美语化 kilometer/fiber;第四册第43课·U8开工)','从研究生命起源的人的工作中,我们必然得出结论:只要有一颗大致像我们这样的行星,生命几乎必定会开始。在我们的太阳系所有行星中,如今我们相当确定,地球是唯一能有生命存活的一颗。火星太干、氧气太少,金星和水星又太热,而外围的行星则接近绝对零度,裹在充满氢气的敌对大气里。但别的‘太阳’——天文学家这样称呼恒星——必定也有像我们这样的行星;而由于恒星的数目如此之多,这个单纯的可能性便几乎成了确定无疑。仅在我们自己的星系里就有一千亿颗恒星,而整个宇宙里的总数如今被估计为约三亿亿颗。尽管在某处开始的生命,或许只有百分之一会发展成复杂、有智慧的形态,可行星的数目如此之多,以致智慧生命必然是宇宙中自然的一部分。既然我们如此确信别的心智存在,那为什么至今没有来自外太空的访客?首先,他们也许在数千、甚至数百万年前就来过这颗行星,却发现我们当时的状态太过原始,对他们先进的知识毫无吸引力。一个高等文明,在对我们太阳系的一次短暂造访中,很可能已经留下了一个自动信使,以等待一个更先进的族群可能的觉醒。然而在这里,我们撞上了所有障碍中最难的一个:把我们隔开的天文距离。平均而言,我们的邻居也许在一百光年之外——而一光年,就是光以每秒十八万六千英里的速度在一年里走过的距离。我们如今的化学火箭,虽足以把人送入轨道,却根本没机会抵达哪怕最近的另一颗恒星——它在四光年之外——更别提几十、几百光年的距离了。所幸,正如一位科普作家在一本名著里所说,我们有一种独一无二、合乎理性的方式,可以向别的智慧生命发出信号。它取决于一个精确的射电频率:21厘米波长,也就是每秒1420兆周,是漂浮在太空中的氢原子自然发出的。这一发射最早于1951年在地球上被探测到;它必定为宇宙中任何地方的射电天文学家所知。一旦这个波长被发现,不久就有人提议把它用作星际讯息那唯一清晰可辨的频率。若没有这类东西,在别的世界上搜寻心智,就像在一座巨大的城市里、没有约定的会合地点去见一位朋友,只能永远在街头游荡,指望一次偶然的相遇。','{"q":"Listen and answer — What does the ''uniquely rational way'' for us to communicate with other intelligent beings in space depend on?","options":["A precise natural radio frequency — the 21-cm hydrogen wavelength — that any radio astronomer would know","Sending chemical rockets to every star","Building giant telescopes on Mars","Waiting for aliens to land on Earth"],"answer_index":0}'::jsonb,'{"title":"be bound to do / may have done / so + 形容词 + 倒装 / let alone / it was not long before","intro":"①be bound to do:‘必定/注定要…’。②may/might + have + 过去分词:对过去的推测,‘可能已经…’。③so + 形容词 + 倒装:so vast is the number that …(把 so + 形容词提前引起主谓倒装)。④let alone:‘更不用说…’,前句多为否定。⑤it was not long before …:‘不久就…’。","table":{"headers":["用法","结构","例子"],"rows":[["be bound to do","be bound + to do","are bound to have planets"],["may have done","may/might + have + 过去分词","may have come long ago"],["so + 形容词 + 倒装","So + 形容词 + be + 主语 + that","So vast is the number that …"],["let alone","…, let alone + 名词/原形","cannot reach the star, let alone galaxies"],["it was not long before","It was not long before + 从句","It was not long before … was suggested"]]},"specialRules":[{"rule":"so + 形容词/副词 放句首时,主句要部分倒装:So vast is the number …(be/助动词提到主语前)。","mark":"So + 形容词 + 倒装"},{"rule":"may/might have done 表对‘过去’的推测;must have done 表肯定推测,can''t have done 表否定推测。","mark":"may have done"},{"rule":"美式拼写:kilometer(千米,英式 kilometre)、fiber(纤维,英式 fibre)。本课已按美语写。","mark":"kilometer / fiber"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET book_no=EXCLUDED.book_no,title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question,grammar_card=EXCLUDED.grammar_card;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l43',1,NULL,'From the work of those who have studied the origin of life, we must conclude that, given a planet only roughly like our own, life is almost certain to begin. Of all the planets in our solar system, we are now fairly sure that the Earth is the only one on which life can survive. Mars is too dry and poor in oxygen, Venus and Mercury are far too hot, and the outer planets lie near absolute zero, wrapped in hostile atmospheres of hydrogen.','从研究生命起源的人的工作中,我们必然得出结论:只要有一颗大致像我们这样的行星,生命几乎必定会开始。在我们的太阳系所有行星中,如今我们相当确定,地球是唯一能有生命存活的一颗。火星太干、氧气太少,金星和水星又太热,而外围的行星则接近绝对零度,裹在充满氢气的敌对大气里。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l43',2,NULL,'But other suns, as astronomers call the stars, are bound to have planets like our own, and since the number of stars is so vast, this mere possibility becomes a virtual certainty. There are a hundred thousand million stars in our own galaxy alone, and the total in the universe is now put at some three hundred million million.','但别的‘太阳’——天文学家这样称呼恒星——必定也有像我们这样的行星;而由于恒星的数目如此之多,这个单纯的可能性便几乎成了确定无疑。仅在我们自己的星系里就有一千亿颗恒星,而整个宇宙里的总数如今被估计为约三亿亿颗。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l43',3,NULL,'Although perhaps only one per cent of the life that begins somewhere will ever develop into complex, intelligent patterns, so vast is the number of planets that intelligent life is bound to be a natural part of the universe. If, then, we are so certain that other minds exist, why have we had no visitors from outer space?','尽管在某处开始的生命,或许只有百分之一会发展成复杂、有智慧的形态,可行星的数目如此之多,以致智慧生命必然是宇宙中自然的一部分。既然我们如此确信别的心智存在,那为什么至今没有来自外太空的访客?') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l43',4,NULL,'First, they may have come to this planet thousands, or even millions, of years ago, and found our prevailing state so primitive that it held no interest for their advanced knowledge. A superior civilization, on a brief visit to our solar system, may well have left an automatic messenger behind, to await the possible awakening of a more advanced people. Here, however, we come up against the most difficult of all obstacles: the astronomical distances that separate us.','首先,他们也许在数千、甚至数百万年前就来过这颗行星,却发现我们当时的状态太过原始,对他们先进的知识毫无吸引力。一个高等文明,在对我们太阳系的一次短暂造访中,很可能已经留下了一个自动信使,以等待一个更先进的族群可能的觉醒。然而在这里,我们撞上了所有障碍中最难的一个:把我们隔开的天文距离。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l43',5,NULL,'Fortunately, as one science writer has put it in a well-known book, there is a uniquely rational way for us to signal to other intelligent beings. It depends on one exact radio frequency: the 21-cm wavelength, or 1420 megacycles a second, naturally given off by the hydrogen atoms that drift through space. Once the wavelength had been found, it was not long before someone proposed using it as the one clearly recognizable frequency for interstellar messages. Without something of this kind, searching for minds on other worlds would be like trying to meet a friend in a huge city with no agreed rendezvous.','所幸,正如一位科普作家在一本名著里所说,我们有一种独一无二、合乎理性的方式,可以向别的智慧生命发出信号。它取决于一个精确的射电频率:21厘米波长,也就是每秒1420兆周,是漂浮在太空中的氢原子自然发出的。一旦这个波长被发现,不久就有人提议把它用作星际讯息那唯一清晰可辨的频率。若没有这类东西,在别的世界上搜寻心智,就像在一座巨大的城市里、没有约定的会合地点去见一位朋友。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
